<?php
namespace Tests\Feature\InternalGames;
use Tests\TestCase;
use Tests\Support\BlackjackFixture;
use Illuminate\Foundation\Testing\DatabaseTransactions;
use App\Models\{CmsGame,InternalGameSession,InternalGameCrashRound};
use App\Services\InternalGames\SkyRushEngine;
class SkyRushHttpBoundaryTest extends TestCase {
 use DatabaseTransactions,BlackjackFixture;
 protected function setUp():void{parent::setUp();$this->withCredentials();$this->setupBlackjack('500.00',false);(new \Database\Seeders\InternalCrashFamilySeeder)->run();}
 private function login():void{$this->postJson('/cms/login',['email'=>$this->player->username,'password'=>'Blackjack-Local-927!'],['X-Requested-With'=>'XMLHttpRequest'])->assertJsonPath('status',200);$this->withCookie(config('session.cookie'),session()->getId());}
 private function launch(string $code,string $mode):string{$r=$this->post('/cms/games/'.$code.'/launch',['playType'=>$mode]);$r->assertRedirect();$this->withCookie(config('session.cookie'),session()->getId());return basename($r->headers->get('Location'));}
 public function test_both_native_surfaces_four_modes_http_bets_cashout_history_reload_and_canonical_finance():void{$this->login();foreach(['sky-rush','orbit-x']as $code)foreach(['demo','real']as $mode){$token=$this->launch($code,$mode);$this->get('/cms/internal-games/play/'.$token)->assertOk()->assertSee($code==='sky-rush'?'cashoutButton2':'data-orbit-lane="2"',false);$before=$this->financeHash();$snap=$this->getJson('/cms/internal-games/skyrush/snapshot?sessionToken='.$token)->assertOk()->json('data');$request=['sessionToken'=>$token,'betAmount'=>'10.00','lane'=>1,'requestKey'=>'http-crash-bet','crashRoundId'=>$snap['currentRound']['id']];$bet=$this->postJson('/cms/internal-games/skyrush/bet',$request)->assertOk()->json('data');$this->postJson('/cms/internal-games/skyrush/bet',$request)->assertOk()->assertJsonPath('data.roundId',$bet['roundId']);$request['lane']=2;$request['requestKey']='http-lane-two';$this->postJson('/cms/internal-games/skyrush/bet',$request)->assertOk();$r=InternalGameCrashRound::where('round_public_id',$bet['crashRoundId'])->firstOrFail();$this->travelTo($r->starts_at->copy()->addMilliseconds(1));$cash=['sessionToken'=>$token,'betRoundId'=>$bet['roundId'],'requestKey'=>'http-cashout'];$this->postJson('/cms/internal-games/skyrush/cashout',$cash)->assertOk()->assertJsonPath('data.status','settled_win');$this->get('/cms/internal-games/play/'.$token)->assertOk();$this->travelTo($r->crashed_at);$this->getJson('/cms/internal-games/skyrush/snapshot?sessionToken='.$token)->assertOk()->assertJsonPath('data.myBets.2.status','settled_loss')->assertJsonCount(2,'data.myBetHistory');$this->assertNotSame($before,$this->financeHash());$this->travelTo($r->crashed_at->copy()->addMinute());}$this->travelBack();$this->reconcileBlackjack();}
 public function test_untrusted_result_wallet_time_amount_lane_and_conflicting_round_rejected():void{$this->login();$t=$this->launch('sky-rush','real');$snap=$this->getJson('/cms/internal-games/skyrush/snapshot?sessionToken='.$t)->assertOk()->json('data');$base=['sessionToken'=>$t,'betAmount'=>'10','lane'=>1,'requestKey'=>'http-boundary','crashRoundId'=>$snap['currentRound']['id']];$before=$this->financeHash();foreach(['result'=>['win'=>true],'multiplier'=>9,'cashoutAmount'=>999,'wallet_account_id'=>999,'currency'=>'USD','crashedAt'=>'2099-01-01']as $k=>$v)$this->postJson('/cms/internal-games/skyrush/bet',$base+[$k=>$v])->assertUnprocessable();$bad=$base;$bad['lane']=3;$this->postJson('/cms/internal-games/skyrush/bet',$bad)->assertUnprocessable();$bad=$base;$bad['crashRoundId']='igcr_wrong';$this->postJson('/cms/internal-games/skyrush/bet',$bad)->assertConflict();$this->assertSame($before,$this->financeHash());}
 public function test_native_expired_maintenance_hidden_guest_and_foreign_round_rejections():void{$this->post('/cms/games/orbit-x/launch',['playType'=>'real'])->assertForbidden();$this->login();$t=$this->launch('orbit-x','real');$s=InternalGameSession::where('session_token',$t)->firstOrFail();$before=$this->financeHash();$this->postJson('/cms/internal-games/skyrush/cashout',['sessionToken'=>$t,'betRoundId'=>'igr_foreign','requestKey'=>'foreign-round'])->assertNotFound();$s->update(['expires_at'=>now()->subSecond()]);$this->getJson('/cms/internal-games/skyrush/snapshot?sessionToken='.$t)->assertGone();$s->update(['expires_at'=>now()->addMinute()]);$s->game->update(['is_maintenance'=>true]);$this->getJson('/cms/internal-games/skyrush/snapshot?sessionToken='.$t)->assertServiceUnavailable();$s->game->update(['is_maintenance'=>false,'status'=>'passive']);$this->get('/cms/games/orbit-x')->assertNotFound();$this->assertSame($before,$this->financeHash());}
}
